//! Reading a file's meta dictionary, checked against what upstream `pyaaf2` reads.
//!
//! The manifests here list every class and type each fixture file *stores* —
//! not pyaaf2's built-in tables merged with them, which is a larger set. They
//! were generated by reading the same property entries out of the same
//! objects, so a match means this port reads the file's own definitions the
//! way pyaaf2 does.

mod common;

use std::fmt::Write as _;
use std::fs::File;

use aaf::{AafFile, MetaDictionary, TypeKind};

use common::{data_dir, read_metadict_manifest};

fn read(name: &str) -> (AafFile<File>, MetaDictionary) {
    let path = data_dir().join(name);
    let mut file =
        AafFile::open(File::open(&path).expect("fixture is readable")).expect("fixture opens");
    let metadict = MetaDictionary::stored_in(&mut file).expect("meta dictionary reads");
    (file, metadict)
}

/// Renders the definitions the way the manifests record them.
fn render(metadict: &MetaDictionary) -> Vec<String> {
    let mut rows = Vec::new();

    for class in metadict.classes() {
        let properties = class
            .properties
            .iter()
            .map(|p| {
                format!(
                    "{}:{}:{}:{}:{}:{}",
                    p.pid,
                    p.name,
                    p.auid,
                    p.type_id,
                    u8::from(p.optional),
                    u8::from(p.unique)
                )
            })
            .collect::<Vec<_>>()
            .join("|");
        rows.push(format!(
            "C\t{}\t{}\t{}\t{}\t{properties}",
            class.auid,
            class.name,
            class.parent,
            u8::from(class.concrete)
        ));
    }

    for type_def in metadict.types() {
        let (category, detail) = match &type_def.kind {
            TypeKind::Int { size, signed } => ("int", format!("{size},{}", u8::from(*signed))),
            TypeKind::StrongRef { target } => ("strongref", target.to_string()),
            TypeKind::WeakRef { target, target_set } => (
                "weakref",
                format!(
                    "{target};{}",
                    join(target_set.iter().map(ToString::to_string))
                ),
            ),
            TypeKind::Enum {
                element_type,
                elements,
            } => (
                "enum",
                format!(
                    "{element_type};{}",
                    join(elements.iter().map(|(v, n)| format!("{v}={n}")))
                ),
            ),
            TypeKind::FixedArray {
                element_type,
                count,
            } => ("fixed", format!("{element_type},{count}")),
            TypeKind::VarArray { element_type } => ("var", element_type.to_string()),
            TypeKind::Set { element_type } => ("set", element_type.to_string()),
            TypeKind::String { element_type } => ("string", element_type.to_string()),
            TypeKind::Stream => ("stream", "-".to_owned()),
            TypeKind::Record { members } => (
                "record",
                join(members.iter().map(|(n, t)| format!("{n}={t}"))),
            ),
            TypeKind::Rename { renamed } => ("rename", renamed.to_string()),
            TypeKind::ExtEnum { elements } => (
                "extenum",
                join(elements.iter().map(|(v, n)| format!("{v}={n}"))),
            ),
            TypeKind::Indirect => ("indirect", "-".to_owned()),
            TypeKind::Opaque => ("opaque", "-".to_owned()),
            TypeKind::Character => ("char", "-".to_owned()),
            // A generic character carries its width in the file rather than in
            // the type, which is the one category this crate does not model.
            TypeKind::Unknown { .. } => ("unknown", "-".to_owned()),
            other => panic!("this test does not know how to describe {other:?}"),
        };
        rows.push(format!(
            "T\t{}\t{}\t{category}\t{detail}",
            type_def.auid, type_def.name
        ));
    }

    rows.sort();
    rows
}

fn join(parts: impl Iterator<Item = String>) -> String {
    let mut out = String::new();
    for (i, part) in parts.enumerate() {
        if i > 0 {
            out.push(',');
        }
        let _ = write!(out, "{part}");
    }
    out
}

/// Every class and type both files define, against `pyaaf2`.
///
/// For classes that is the name, parent, concreteness and every property the
/// class declares, with each property's pid, name, identity, type and flags.
/// For types it is the category and whatever that category needs: an
/// integer's width and signedness, an array's element type, an enumeration's
/// elements, a record's members in order.
#[test]
fn matches_pyaaf2_on_every_definition() {
    for (fixture, manifest, classes, types) in [
        ("empty.aaf", "empty.metadict.tsv", 44, 81),
        (
            "sector_size_512.aaf",
            "sector_size_512.metadict.tsv",
            60,
            108,
        ),
    ] {
        let expected = read_metadict_manifest(manifest);
        let (_, metadict) = read(fixture);

        assert_eq!(metadict.class_count(), classes, "{fixture}: class count");
        assert_eq!(metadict.type_count(), types, "{fixture}: type count");

        let actual = render(&metadict);
        assert_eq!(actual.len(), expected.len(), "{fixture}: definition count");
        for (actual, expected) in actual.iter().zip(&expected) {
            assert_eq!(actual, expected, "{fixture}: definitions diverge");
        }
    }
}

#[test]
fn property_names_come_from_the_file_itself() {
    let (mut file, metadict) = read("empty.aaf");
    let root = file.root().expect("root reads");

    let header = file
        .children(&root)
        .expect("children read")
        .into_iter()
        .find(|(pid, _)| *pid == 2)
        .expect("the root owns a header")
        .1;

    let class = metadict
        .class(header.class_id())
        .expect("the header's class is defined");
    assert_eq!(class.name, "Header");

    // Every property the header stores is one its class declares, so the
    // dictionary turns the whole object into named fields.
    for property in header.properties() {
        let def = metadict
            .property(header.class_id(), property.pid)
            .unwrap_or_else(|| panic!("{:#06x} should be defined", property.pid));
        assert_eq!(def.pid, property.pid);
        assert!(!def.name.is_empty());
        assert!(metadict.type_def(def.type_id).is_some(), "{}", def.name);
    }
    assert!(header.properties().iter().any(|p| {
        metadict
            .property(header.class_id(), p.pid)
            .is_some_and(|d| d.name == "Content")
    }));
}

/// The file's own dictionary does not define every class the file uses.
///
/// The root object's class is the clearest case: `Root` is part of the format
/// rather than of any file, so nothing stores it and nothing in the file says
/// that property 1 is the meta dictionary and property 2 the header. Reading
/// those names needs the built-in definitions that are not ported yet, so
/// this records the gap rather than hiding it.
#[test]
fn the_root_class_is_not_in_the_files_dictionary() {
    let (mut file, metadict) = read("empty.aaf");
    let root = file.root().expect("root reads");

    assert_eq!(
        root.class_id().to_string(),
        "b3b398a5-1c90-11d4-8053-080036210804"
    );
    assert_eq!(metadict.class(root.class_id()), None);
    assert_eq!(metadict.class_named("Root"), None);
    assert_eq!(metadict.property(root.class_id(), 1), None);
}

#[test]
fn classes_inherit_their_parents_properties() {
    let (_, metadict) = read("empty.aaf");

    let interchange = metadict
        .class_named("InterchangeObject")
        .expect("the root class is defined");
    // The root of the inheritance tree is recorded as its own parent.
    assert_eq!(interchange.parent, interchange.auid);
    assert_eq!(metadict.parent(interchange), None);

    let mob_slot = metadict.class_named("MobSlot").expect("MobSlot is defined");
    assert!(!mob_slot.properties.is_empty());

    // Everything inherits from InterchangeObject, so every class has at least
    // its properties, and its own come last.
    let all = metadict.all_properties(mob_slot.auid);
    assert!(all.len() > mob_slot.properties.len());
    for property in &interchange.properties {
        assert!(
            all.iter().any(|p| p.pid == property.pid),
            "MobSlot should inherit {}",
            property.name
        );
    }
    let own: Vec<_> = all[all.len() - mob_slot.properties.len()..]
        .iter()
        .map(|p| p.pid)
        .collect();
    assert_eq!(
        own,
        mob_slot
            .properties
            .iter()
            .map(|p| p.pid)
            .collect::<Vec<_>>()
    );
}

#[test]
fn mobs_are_keyed_by_their_mob_id() {
    let (_, metadict) = read("empty.aaf");

    // A set of objects is keyed by whichever property the class marks unique.
    let mob = metadict.class_named("Mob").expect("Mob is defined");
    let pid = metadict
        .unique_key_pid(mob.auid)
        .expect("Mob has a unique key");
    let key = metadict
        .property(mob.auid, pid)
        .expect("the key is defined");
    assert_eq!(key.name, "MobID");
    assert!(key.unique);

    // Which is a MobID, the 32-byte identifier, not an AUID.
    let type_def = metadict
        .type_def(key.type_id)
        .expect("MobIDType is defined");
    assert_eq!(type_def.name, "MobIDType");
    assert!(matches!(type_def.kind, TypeKind::Record { .. }));
}

/// Which of AAF's type categories these fixtures between them define.
///
/// Sixteen categories exist. The fixtures define fifteen of them, which is
/// every one this crate models; the one missing is `GenericCharacter`, whose
/// class id sits outside the meta range and which neither file uses.
#[test]
fn reads_every_type_category_the_fixtures_use() {
    let mut categories = std::collections::HashSet::new();
    for fixture in ["empty.aaf", "sector_size_512.aaf"] {
        let (_, metadict) = read(fixture);
        for type_def in metadict.types() {
            assert!(
                !matches!(type_def.kind, TypeKind::Unknown { .. }),
                "{} ({}) has an unrecognised category",
                type_def.name,
                type_def.auid
            );
            assert!(!type_def.name.is_empty(), "{} has no name", type_def.auid);
            categories.insert(std::mem::discriminant(&type_def.kind));
        }
    }
    assert_eq!(categories.len(), 15);
}

#[test]
fn a_rational_is_a_record_of_two_integers() {
    let (_, metadict) = read("sector_size_512.aaf");

    // This is the type that will bridge AAF and opentime's RationalTime.
    let rational = metadict
        .type_named("Rational")
        .expect("Rational is defined");
    let TypeKind::Record { members } = &rational.kind else {
        panic!("Rational should be a record");
    };
    assert_eq!(members.len(), 2);
    assert_eq!(members[0].0, "Numerator");
    assert_eq!(members[1].0, "Denominator");
    for (_, type_id) in members {
        let member = metadict.type_def(*type_id).expect("member type is defined");
        assert!(matches!(
            member.kind,
            TypeKind::Int {
                size: 4,
                signed: true
            }
        ));
    }
}

/// The dictionary a file is actually read with, against `pyaaf2`'s.
///
/// [`MetaDictionary::read`] lays a file's own definitions over the ones AAF
/// takes as given, which is how pyaaf2 ends up with a dictionary too. The
/// `*.merged.tsv` manifests record pyaaf2's, so this checks the built-in
/// tables and the merge together rather than either alone.
///
/// One thing the manifests leave out: AAF defines 68 properties with no
/// identifier of their own, which a file assigns one to if it uses one.
/// pyaaf2 gives every one of them a placeholder counting down from `0xffff`
/// whether the file uses it or not. Those placeholders are its bookkeeping
/// rather than anything in the file, so neither side records them.
#[test]
fn matches_pyaaf2_on_the_dictionary_a_file_is_read_with() {
    for (fixture, manifest, classes, types) in [
        ("empty.aaf", "empty.merged.tsv", 116, 164),
        (
            "sector_size_512.aaf",
            "sector_size_512.merged.tsv",
            117,
            164,
        ),
    ] {
        let path = data_dir().join(fixture);
        let mut file =
            AafFile::open(File::open(&path).expect("fixture is readable")).expect("fixture opens");
        let metadict = MetaDictionary::read(&mut file).expect("meta dictionary reads");

        assert_eq!(metadict.class_count(), classes, "{fixture}: class count");
        assert_eq!(metadict.type_count(), types, "{fixture}: type count");

        let expected = read_metadict_manifest(manifest);
        let found = render(&metadict);
        assert_eq!(found.len(), expected.len(), "{fixture}: row count");
        for (row, want) in found.iter().zip(&expected) {
            assert_eq!(row, want, "{fixture}: definitions diverge");
        }
    }
}
